def detail_bank(split):
    start = {'train': 0, 'validation': 2, 'test': 4}[split]
    return {c: rows[start:start + 2] for c, rows in DETAILS.items()}

def service_bank(split):
    sl = {'train': slice(0, 12), 'validation': slice(12, 18), 'test': slice(18, 24)}[split]
    return {c: rows[sl] for c, rows in SERVICES.items()}
